int font_lookup(int cp, const unsigned short **rows)
{
    for (int i = 0; i < FONT_N; i++) {
        if (FONT_CP[i] == (unsigned)cp) {
            *rows = FONT_GLYPH[i];
            return 1;
        }
    }
    return 0;
}
